"""A ledger of orders."""


class OrderLedger:
    def __init__(self, orders=()):
        self._orders = list(orders)

    def orders(self):
        """Return the orders held (a copy, so callers cannot change the ledger)."""
        return list(self._orders)

    def add(self, order):
        """Add one order to the ledger."""
        self.orders().append(order)

    def total(self):
        """Return the total amount of the orders held."""
        return sum(x.amount for x in self._orders)


def largest_amount(orders):
    """Return the largest amount, or None when there are no orders."""
    values = [x.amount for x in orders]
    return max(values) if values else None


def customer_names(orders):
    """Return the distinct customer values, in first-seen order."""
    names = []
    for x in orders:
        if x.customer not in names:
            names.append(x.customer)
    return names

